const app=document.querySelector('#app');let universeList=LOCAL_UNIVERSES,selected=null,stream=null;
const sleep=t=>new Promise(r=>setTimeout(r,t));
function render(html){app.innerHTML=html;window.scrollTo(0,0);bindActions()}
function artStyle(u){return `--theme:${u.color};--art:url('images/parallel-realms.png')`}
function button(label,action,klass='primary'){return `<button class="button ${klass}" data-action="${action}"><span>${label}</span><b>↗</b></button>`}
function landing(){render(document.querySelector('#landing-template').innerHTML)}
async function beginScan(){render(`<section class="screen scanner"><div class="scanner-wrap"><p class="eyebrow"><i></i> CAMERA IS LOCAL ONLY · NO IMAGE STORAGE</p><div class="scanner-frame"><video id="camera" autoplay playsinline muted></video><div id="placeholder" class="scan-placeholder"><div class="silhouette"></div></div><div class="scanline"></div></div><div class="frame-text"><span>BIOMETRIC VECTOR / LIVE</span><span id="percent">0%</span></div><div class="progress"><i id="bar"></i></div><div id="scan-status" class="scan-status">INITIALIZING OPTICS...</div><p id="scan-detail" class="scan-detail">AWAITING DIMENSIONAL SIGNATURE</p></div></section>`);let video=document.querySelector('#camera'),ph=document.querySelector('#placeholder');try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=stream;ph.classList.add('hidden')}catch{document.querySelector('#scan-detail').textContent='CAMERA PREVIEW SIMULATION · PERMISSION OPTIONAL'}const steps=[['SCANNING PERSON...',25],['ANALYZING DIMENSIONAL SIGNATURE...',50],['MAPPING REALITY LAYER...',75],['PERSON DETECTED ✓',100]];for(const[s,p]of steps){await sleep(900);document.querySelector('#scan-status').textContent=s;document.querySelector('#bar').style.width=p+'%';document.querySelector('#percent').textContent=p+'%'}await sleep(950);stopCamera();earth()}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function earth(){render(`<section class="screen earth-screen"><div class="earth-large"></div><div class="earth-copy"><p class="eyebrow"><i></i> DIMENSIONAL LOCATION IDENTIFIED</p><h2>YOU ARE CURRENTLY IN: <span>EARTH</span> 🌍</h2><p>Your original reality has been confirmed.</p>${button('EXPLORE OTHER UNIVERSES','select','ghost')}</div></section>`)}
async function selectScreen(){try{const r=await fetch('/api/universes');if(r.ok){const api=await r.json();universeList=LOCAL_UNIVERSES.map(local=>({...local,...api.find(item=>item.id===local.id)}))}}catch{}const cards=universeList.map((u,i)=>`<article class="universe-card" style="${artStyle(u)}"><span class="number">0${i+1} · ${u.color}</span><h3>${u.name}</h3><p>${u.tag}</p><button class="card-button" data-action="explore" data-id="${u.id}">EXPLORE ↗</button></article>`).join('');render(`<section class="screen selection"><header><p class="eyebrow"><i></i> REALITY ARCHIVE · 06 AVAILABLE</p><h2 class="section-title">CHOOSE YOUR <em>UNIVERSE</em></h2><p>Every universe contains a different version of you.</p></header><div class="universe-grid">${cards}</div><div class="random-wrap">${button('🎲 RANDOM UNIVERSE','random','random')}</div></section>`)}
function profile(id){selected=universeList.find(u=>u.id===id)||LOCAL_UNIVERSES[0];let u=selected,d=u.identity;render(`<section class="universe-stage" style="${artStyle(u)}"><header class="topbar"><span class="hud">DIMENSIONAL PROFILE / ${u.id.toUpperCase()}</span><button class="back" data-action="select">← CHANGE UNIVERSE</button></header><div class="profile-hero"><p class="eyebrow"><i></i> ${u.tag.toUpperCase()}</p><h1>YOUR LIFE IN <span>${u.name}</span></h1><p class="intro">A fictional possibility from a reality where your story took a very different turn.</p></div><div class="profile-layout"><article class="glass"><h3>IDENTITY</h3><h2 class="identity-name">${d.name}</h2><div class="chips"><span class="chip">${d.species}</span><span class="chip">${d.status}</span></div><dl class="specs"><div><dt>AGE</dt><dd>${d.age}</dd></div><div><dt>GENDER</dt><dd>${d.gender}</dd></div><div><dt>UNIVERSE</dt><dd>${u.name}</dd></div><div><dt>BIRTHPLACE</dt><dd>${d.birthplace}</dd></div><div><dt>OCCUPATION</dt><dd>${d.occupation}</dd></div><div><dt>GIFT</dt><dd>${d.abilities}</dd></div></dl></article><article class="glass"><h3>POWERS / ABILITIES</h3>${u.powers.map(p=>`<div class="power"><b>${p[0]}</b><span>${p[1]}</span></div>`).join('')}</article></div><div class="details"><article class="glass detail-card"><h3>FAMILY</h3><p><b>FATHER</b><br>${u.family.father}</p><p><b>MOTHER</b><br>${u.family.mother}</p><p><b>SIBLINGS</b><br>${u.family.siblings}</p></article><article class="glass detail-card"><h3>RELATIONSHIP / CHILDREN</h3><p>${u.relationship}</p><p><b>CHILDREN</b><br>${u.children}</p></article><article class="glass detail-card"><h3>CAREER & HOME</h3><p><b>${d.occupation}</b><br>${u.career.rank}</p><p><b>HOME</b><br>${u.career.home}</p><p><b>GREATEST ACHIEVEMENT</b><br>${u.career.achievement}</p><p><b>BIGGEST FAILURE</b><br>${u.career.failure}</p></article></div><div class="full glass"><h3>ALTERNATE PERSONALITY</h3><p>${u.personality}</p><h3 style="margin-top:24px">FUN FACTS</h3><ul>${u.facts.map(f=>`<li>${f}</li>`).join('')}</ul><div style="margin-top:25px">${button('✨ SEE MY STORY','story','ghost')}</div></div><section class="switch"><p class="eyebrow"><i></i> A CHOICE ACROSS REALITIES</p><h2>ARE YOU INTERESTED IN SWITCHING<br>TO THIS UNIVERSE?</h2><p>Your current reality is waiting. But another life is calling.</p><div class="buttons">${button('YES — SWITCH UNIVERSE','transfer')}${button('NO — REJECT UNIVERSE','reject','reject')}</div></section><aside id="story-modal" class="story-modal hidden"><article class="story-panel" style="${artStyle(u)}"><button class="close-story" data-action="close-story">× BACK TO MY PROFILE</button><p class="eyebrow">YOUR STORY IN THIS UNIVERSE</p><h2>${d.name} / ${u.name}</h2>${u.story.map(p=>`<p>${p}</p>`).join('')}</article></aside></section>`)}
async function transfer(){let u=selected;render(`<section class="screen transfer" style="${artStyle(u)}"><div class="portal"></div><div class="transfer-content"><p class="eyebrow"><i></i> DIMENSIONAL GATEWAY ONLINE</p><h2 id="transfer-status">UNIVERSE SWITCH INITIATED</h2><p id="transfer-detail" class="scan-detail">STABILIZING DIMENSIONAL GATEWAY...</p><div class="progress"><i id="transfer-bar"></i></div><p id="transfer-percent" class="micro">0% / REALITY ALIGNMENT</p></div></section>`);for(let p=0;p<=100;p+=20){await sleep(580);document.querySelector('#transfer-bar').style.width=p+'%';document.querySelector('#transfer-percent').textContent=`${p}% / REALITY ALIGNMENT`;document.querySelector('#transfer-detail').textContent=p<50?'SYNCHRONIZING IDENTITY...':p<100?'TRANSFERRING CONSCIOUSNESS...':'REALITY ALIGNMENT: 100%'}await sleep(800);render(`<section class="screen final" style="${artStyle(u)}"><article class="glass"><p class="eyebrow"><i></i> DIMENSIONAL TRANSFER COMPLETE</p><h1>YOU ARE CURRENTLY IN:<br><span style="color:var(--theme)">${u.name}</span></h1><p>Welcome to your new reality.</p>${button('ENTER THE UNIVERSE','enter')}</article></section>`)}
function final(){let u=selected,d=u.identity;render(`<section class="screen final" style="${artStyle(u)}"><article class="glass"><p class="eyebrow"><i></i> NEW REALITY UNLOCKED</p><h1>WELCOME TO <span style="color:var(--theme)">${u.name}</span></h1><p>Your new life begins now.</p><div class="mini-profile"><div><b>NAME</b>${d.name}</div><div><b>AGE</b>${d.age}</div><div><b>OCCUPATION</b>${d.occupation}</div><div><b>RELATIONSHIP</b>${u.relationship.split('·')[0]}</div><div><b>HOME</b>${u.career.home.split('·')[0]}</div><div><b>SPECIAL ABILITY</b>${u.powers[0][1]}</div></div>${button('EXPLORE ANOTHER REALITY','select','ghost')}</article></section>`)}
function reject(){render(`<section class="screen transfer" style="--theme:#9fb1c6"><div class="transfer-content"><p class="eyebrow"><i></i> TRANSFER CANCELLED</p><h2>UNIVERSE REJECTED ❌</h2><p class="scan-detail">REALITY REMAINS UNCHANGED.</p><div style="margin-top:30px">${button('EXPLORE ANOTHER UNIVERSE','select','ghost')}</div></div></section>`)}
function bindActions(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>{let a=el.dataset.action;if(a==='scan')beginScan();else if(a==='select')selectScreen();else if(a==='explore')profile(el.dataset.id);else if(a==='random')profile(universeList[Math.floor(Math.random()*universeList.length)].id);else if(a==='story')document.querySelector('#story-modal').classList.remove('hidden');else if(a==='close-story')document.querySelector('#story-modal').classList.add('hidden');else if(a==='transfer')transfer();else if(a==='enter')final();else if(a==='reject')reject()}))}landing();
